function maxCount(banned, n, maxSum) {
  const bannedSet = new Set(banned);
  let total = 0;
  let count = 0;
  for (let value = 1; value <= n; value++) {
    if (bannedSet.has(value)) {
      continue;
    }
    if (total + value > maxSum) {
      break;
    }
    total += value;
    count++;
  }
  return count;
}

