function maxCount(banned, n, maxSum) {
  // Start with every allowed value, then drop the largest one until the sum fits.
  const allowed = [];
  for (let v = 1; v <= n; v++) if (!banned.includes(v)) allowed.push(v);
  let sum = allowed.reduce((a, b) => a + b, 0);
  while (sum > maxSum) sum -= allowed.pop();
  return allowed.length;
}

